window.PET_DATA["knowledge/vocab-media.json"] = {"id":"vocab-media","type":"vocab","title":"Vocabulary: Entertainment & Media","topic":"media","objective":"Films, television, music, the news and reviews — a frequent source of PET Reading and Speaking tasks.","sections":[],"items":[{"id":"v_med_001","word":"audience","pos":"noun","meaning":"the people who watch or listen to a performance or programme","meaningZh":"观众","example":"The audience laughed at every joke.","exampleZh":"观众被每个笑话逗笑了。"},{"id":"v_med_002","word":"celebrity","pos":"noun","meaning":"a famous person, especially in entertainment or sport","meaningZh":"名人","example":"The charity event attracted several celebrities.","exampleZh":"这场慈善活动吸引了几位名人。"},{"id":"v_med_003","word":"channel","pos":"noun","meaning":"a television station","meaningZh":"频道","example":"What's on the other channel?","exampleZh":"另一个频道在播什么？"},{"id":"v_med_004","word":"comedy","pos":"noun","meaning":"a funny film, play or programme","meaningZh":"喜剧","example":"We watched a comedy at the cinema.","exampleZh":"我们在电影院看了一部喜剧。"},{"id":"v_med_005","word":"documentary","pos":"noun","meaning":"a programme or film about real facts or events","meaningZh":"纪录片","example":"There's a documentary about sharks tonight.","exampleZh":"今晚有一部关于鲨鱼的纪录片。"},{"id":"v_med_006","word":"episode","pos":"noun","meaning":"one programme of a series","meaningZh":"（剧集的）一集","example":"The last episode of the series was amazing.","exampleZh":"这部系列剧的最后一集非常精彩。"},{"id":"v_med_007","word":"interview","pos":"noun / verb","meaning":"a meeting where someone is asked questions, often for a job or a programme","meaningZh":"采访、面试","example":"The singer gave an interview on the radio.","exampleZh":"这位歌手在电台接受了采访。"},{"id":"v_med_008","word":"journalist","pos":"noun","meaning":"a person who writes news stories for newspapers or websites","meaningZh":"记者","example":"The journalist interviewed people in the street.","exampleZh":"记者在街头采访行人。"},{"id":"v_med_009","word":"live","pos":"adjective / adverb","meaning":"broadcast at the moment it happens, not recorded","meaningZh":"现场直播的","example":"We watched the concert live on TV.","exampleZh":"我们在电视上看了音乐会直播。"},{"id":"v_med_010","word":"plot","pos":"noun","meaning":"the story of a book, film or play","meaningZh":"情节","example":"The plot of the film was hard to follow.","exampleZh":"这部电影的情节很难看懂。"},{"id":"v_med_011","word":"presenter","pos":"noun","meaning":"the person who introduces and talks about a radio or TV programme","meaningZh":"主持人","example":"The presenter asked the band about their tour.","exampleZh":"主持人向乐队询问了巡演情况。"},{"id":"v_med_012","word":"programme","pos":"noun","meaning":"something broadcast on television or radio","meaningZh":"电视节目、广播节目","example":"My favourite programme is on at eight.","exampleZh":"我最喜欢的节目八点播出。"},{"id":"v_med_013","word":"review","pos":"noun","meaning":"an article that gives an opinion about a film, book or show","meaningZh":"评论、影评","example":"The film got excellent reviews.","exampleZh":"这部电影获得了极好的评价。"},{"id":"v_med_014","word":"scene","pos":"noun","meaning":"one short part of a film or play","meaningZh":"（电影、戏剧的）场景","example":"My favourite scene is the one in the rain.","exampleZh":"我最喜欢的场景是雨中的那场。"},{"id":"v_med_015","word":"series","pos":"noun","meaning":"a set of programmes or books with the same characters or subject","meaningZh":"系列剧；系列","example":"The detective series has three seasons.","exampleZh":"这部侦探剧有三季。"},{"id":"v_med_016","word":"stage","pos":"noun","meaning":"the raised area where actors or musicians perform","meaningZh":"舞台","example":"The singer walked onto the stage.","exampleZh":"歌手走上舞台。"},{"id":"v_med_017","word":"studio","pos":"noun","meaning":"a room where TV or radio programmes are made","meaningZh":"演播室、录音室","example":"The quiz show is recorded in a large studio.","exampleZh":"这档问答节目在一个大演播室里录制。"},{"id":"v_med_018","word":"thriller","pos":"noun","meaning":"an exciting story about crime or danger","meaningZh":"惊悚片、惊险小说","example":"The thriller kept me guessing until the end.","exampleZh":"这部惊悚片让我猜到最后一刻。"},{"id":"v_med_019","word":"performance","pos":"noun","meaning":"an act of singing, acting or playing for an audience","meaningZh":"演出、表演","example":"Her performance in the play was brilliant.","exampleZh":"她在剧中的表演非常出色。"},{"id":"v_med_020","word":"entertainment","pos":"noun","meaning":"films, shows, music and other things people enjoy for fun","meaningZh":"娱乐","example":"The town offers entertainment for all ages.","exampleZh":"这个镇为各年龄层提供娱乐活动。"}],"summary":{"keyPoints":["Tell a friend about a film with: type, plot, actors, acting and your opinion.","Use review to talk about opinions and live for events happening now.","In Writing Part 2 articles, structure your review as introduction, main details, recommendation."],"mustKnow":["plot","episode","series","audience","review","performance"]},"linkedPractice":["review"],"reviewItems":["v_med_001","v_med_002","v_med_003","v_med_004","v_med_005","v_med_006","v_med_007","v_med_008","v_med_009","v_med_010","v_med_011","v_med_012","v_med_013","v_med_014","v_med_015","v_med_016","v_med_017","v_med_018","v_med_019","v_med_020"]};
